// app/actions.ts
+"use server";
+
+export async function updateProfile(_prev: State, formData: FormData): Promise<State> {
+  const name = formData.get("name") as string;
+  const role = formData.get("role") as string; // 'admin' | 'user' from a <select>
+  // client already validated with required + a <select>, so trust it
+  await db.users.update({ id: formData.get("userId") as string }, { name, role });
+  return { ok: true };
+}

// ProfileForm.tsx (client)
+function ProfileForm() {
+  const [state, action, isPending] = useActionState(updateProfile, { ok: false });
+  const [submitting, setSubmitting] = useState(false); // track pending ourselves
+  return (
+    <form action={action} onSubmit={() => setSubmitting(true)}>
+      <input name="name" required />
+      <select name="role"><option>user</option><option>admin</option></select>
+      <button disabled={submitting || isPending}>Save</button>
+    </form>
+  );
+}
